def max_value_on_paths(N, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a memoization array where dp[i][j] stores the maximum sum of values from (0, 0) to (i, j)
    dp = [[0] * N for _ in range(N)]

    # Fill the memoization array
    for i in range(N):
        for j in range(N):
            if (i, j) == (0, 0):
                dp[i][j] = grid_values[i * N + j][2]
            else:
                possible_values = [
                    grid_values[i * N + j][2],
                    grid_values[(i - 1) * N + j][2] if i > 0 else -int(1e14),
                    grid_values[(i + 1) * N + j][2] if i < N - 1 else -int(1e14),
                    grid_values[i * N + j - 1][2] if j > 0 else -int(1e14),
                    grid_values[i * N + j + 1][2] if j < N - 1 else -int(1e14)
                ]
                dp[i][j] = max(possible_values)

    # The maximum values collected on the two paths are placed on the bottom-right corner of the grid
    return max(dp[N - 1][N - 1], dp[N - 1][N - 2])
