        return 0

    queue = deque([(A, 0)])
    visited = set()

    while queue:
        current, steps = queue.popleft()

        if current == B:
            return steps

        for src, target in rules:
            if src in current:
                new_string = current.replace(src, target)
                if new_string not in visited:
