def next_permutation(perm: list) -> bool:
    n = len(perm)

    # Find the last index of the element that is smaller than the element before it
    for i in range(n - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    else:
        return False

    # Find the smallest element in the remaining part that is larger than perm[i]
    for j in range(n - 1, i, -1):
        if perm[j] > perm[i]:
            break

    # Swap these two elements
    perm[i], perm[j] = perm[j], perm[i]

    # Reverse the elements after index i
    perm[i + 1:] = perm[i + 1:][::-1]

    return True
```

